import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"忧苦","description":"","frontmatter":{"title":"忧苦","date":"2026-11-24T00:00:00.000Z","seq":53,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"刘向","source_book":"楚辞","prev":{"text":"惜贤","link":"/blogs/楚辞/惜贤.html"},"next":{"text":"愍命","link":"/blogs/楚辞/愍命.html"}},"headers":[],"relativePath":"blogs/楚辞/忧苦.md","filePath":"blogs/楚辞/忧苦.md"}'),o={name:"blogs/楚辞/忧苦.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="忧苦" tabindex="-1">忧苦 <a class="header-anchor" href="#忧苦" aria-label="Permalink to &quot;忧苦&quot;">​</a></h1><p class="poem-meta">先秦 · 刘向　·　九叹</p><div class="poem"><p class="poem-stanza">悲余心之悁悁兮，哀故邦之逢殃。</p><p class="poem-stanza">辞九年而不复兮，独茕茕而南行。</p><p class="poem-stanza">思余俗之流风兮，心纷错而不受。</p><p class="poem-stanza">遵野莽以呼风兮，步从容于山廋。</p><p class="poem-stanza">巡陆夷之曲衍兮，幽空虚以寂寞。</p><p class="poem-stanza">倚石岩以流涕兮，忧憔悴而无乐。</p><p class="poem-stanza">登巑岏以长企兮，望南郢而闚之。</p><p class="poem-stanza">山修远其辽辽兮，涂漫漫其无时。</p><p class="poem-stanza">听玄鹤之晨鸣兮，于高冈之峨峨。</p><p class="poem-stanza">独愤积而哀娱兮，翔江洲而安歌。</p><p class="poem-stanza">三鸟飞以自南兮，览其志而欲北。</p><p class="poem-stanza">原寄言于三鸟兮，去飘疾而不可得。</p><p class="poem-stanza">欲迁志而改操兮，心纷结其未离。</p><p class="poem-stanza">外彷徨而游览兮，内恻隐而含哀。</p><p class="poem-stanza">聊须臾以时忘兮，心渐渐其烦错。</p><p class="poem-stanza">原假簧以舒忧兮，志纡郁其难释。</p><p class="poem-stanza">叹《离骚》以扬意兮，犹未殫于《九章》。</p><p class="poem-stanza">长嘘吸以于悒兮，涕横集而成行。</p><p class="poem-stanza">伤明珠之赴泥兮，鱼眼玑之坚藏。</p><p class="poem-stanza">同驽骡与乘駔兮，杂斑駮与阘茸。</p><p class="poem-stanza">葛藟虆于桂树兮，鸱鸮集于木兰。</p><p class="poem-stanza">偓促谈于廊庙兮，律魁放乎山间。</p><p class="poem-stanza">恶虞氏之箫《韶》兮，好遗风之《激楚》。</p><p class="poem-stanza">潜周鼎于江淮兮，爨土鬵于中宇。</p><p class="poem-stanza">且人心之持旧兮，而不可保长。</p><p class="poem-stanza">邅彼南道兮，征夫宵行。</p><p class="poem-stanza">思念郢路兮，还顾睠睠。</p><p class="poem-stanza">涕流交集兮，泣下涟涟。</p><p class="poem-stanza">叹曰：</p><p class="poem-stanza">登山长望中心悲兮，菀彼青青泣如颓兮，</p><p class="poem-stanza">留思北顾涕渐渐兮，折锐摧矜凝氾滥兮，</p><p class="poem-stanza">念我茕茕魂谁求兮，仆夫慌悴散若流兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
